INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('passage_reconstruction', '{"passage": "A new HR manager inherited a team with low morale and high turnover. Rather than making immediate changes, she spent her first month listening to employees individually. Based on their feedback, she introduced flexible scheduling and recognition awards. Within six months, turnover had dropped noticeably."}'::jsonb, '{"key_points": ["a new HR manager inherited a team with low morale", "she spent a month listening to employees", "she introduced flexible scheduling and awards", "turnover dropped within six months"]}'::jsonb, 46, 0.55, 'B2', 'approved', 'exam', 'business', 'd2000000-0000-4000-8000-000000000012', 1),
('passage_reconstruction', '{"passage": "A logistics company noticed repeated delays at one of its regional hubs. After investigating, managers discovered an outdated routing system was the main cause. They installed updated software and retrained the dispatch team. Delivery times at that hub improved significantly within weeks."}'::jsonb, '{"key_points": ["a company noticed delays at a regional hub", "an outdated routing system was the cause", "they installed new software and retrained staff", "delivery times improved within weeks"]}'::jsonb, 42, 0.56, 'B2', 'approved', 'exam', 'business', 'd2000000-0000-4000-8000-000000000012', 2),
('passage_reconstruction', '{"passage": "Thank you for raising your concerns about the recent shift changes. We understand this has affected several employees'' schedules, and we apologize for the short notice given. We are reviewing the policy and will share an updated schedule by the end of this week."}'::jsonb, '{"key_points": ["thanks for raising concerns about shift changes", "apologizes for the short notice", "the policy is being reviewed", "an updated schedule will be shared by week''s end"]}'::jsonb, 44, 0.56, 'B2', 'approved', 'exam', 'business', 'd2000000-0000-4000-8000-000000000012', 3);
