('reading_comprehension', '{"passage": "Warehouse Memo: The new inventory system will go live next Monday. All staff must complete the online training module before then. Supervisors will verify completion by Friday.", "question": "When does the new system go live?", "options": ["This Friday", "Next Monday", "Next Friday", "Immediately"]}'::jsonb, '{"correctIndex": 1}'::jsonb, 0.45, 'B1', 'approved', 'exam', 'business', 'd2000000-0000-4000-8000-000000000013', 5),
