INSERT INTO items (item_type_id, content, answer_set, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('email_writing', '{"prompt": "Your warehouse has had an increase in minor safety incidents recently. Your manager, Mr. Alves, wants ideas for improving safety without large new investments. Write an email to him suggesting three ways to improve safety. Your suggestions must come from the following three themes: refresher training, clearer signage, regular equipment checks. You should include all three themes and provide supporting ideas for each of your suggestions."}'::jsonb, null, 0.58, 'B2', 'approved', 'exam', 'business', 'd2000000-0000-4000-8000-000000000014', 1),
('email_writing', '{"prompt": "Your team is planning its annual recruitment drive. Your manager, Ms. Lindqvist, wants ideas for attracting more qualified applicants. Write an email to her suggesting three ways to improve the recruitment process. Your suggestions must come from the following three themes: referral bonuses, university partnerships, improved job postings. You should include all three themes and provide supporting ideas for each of your suggestions."}'::jsonb, null, 0.58, 'B2', 'approved', 'exam', 'business', 'd2000000-0000-4000-8000-000000000014', 2);
