INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('story_retelling', '{"story": "A warehouse supervisor noticed one employee consistently exceeded productivity targets. Instead of simply praising her privately, he asked her to share her methods with the team. Several coworkers adopted her approach. Overall warehouse productivity rose noticeably within a month."}'::jsonb, null, 42, 0.52, 'B2', 'approved', 'exam', 'business', 'd2000000-0000-4000-8000-00000000001a', 1),
('story_retelling', '{"story": "A manufacturing company struggled with a high rate of equipment breakdowns. An engineer suggested switching to a preventive maintenance schedule instead of fixing issues as they arose. Management approved a trial period. Breakdowns dropped sharply, saving the company significant repair costs."}'::jsonb, null, 45, 0.55, 'B2', 'approved', 'exam', 'business', 'd2000000-0000-4000-8000-00000000001a', 2),
('story_retelling', '{"story": "A recruiter noticed that strong candidates often dropped out during a lengthy interview process. She proposed condensing it from five stages to three. Hiring managers were initially hesitant to change the process. After a trial run, both candidate satisfaction and hiring speed improved significantly."}'::jsonb, null, 47, 0.56, 'B2', 'approved', 'exam', 'business', 'd2000000-0000-4000-8000-00000000001a', 3);
